import com.sun.java.swing.*;
import java.awt.*;

import java.io.*;
import java.net.*;

public class GetURL extends JApplet
{
	public void init()
	{
		// Take out this line if you don't use symantec.itools.net.RelativeURL or symantec.itools.awt.util.StatusScroller
		symantec.itools.lang.Context.setApplet(this);

		// This code is automatically generated by Visual Cafe when you add
		// components to the visual environment. It instantiates and initializes
		// the components. To modify the code, only use code syntax that matches
		// what Visual Cafe can generate, or Visual Cafe may be unable to back
		// parse your Java file into its visual environment.
		//{{INIT_CONTROLS
		getContentPane().setLayout(null);
		setSize(426,266);
		//}}
		
		// The parameters are the url address and the output file name
		main("http://www.darkfish.com/turncoat/Turncoat.class", "Turncoat.class");
	}

	//{{DECLARE_CONTROLS
	//}}
	
	public static void main(String nameURL, String nameFile) {
	    InputStream in = null;
	    OutputStream out = null;
	    try {

	        // Set up the streams
	        URL url = new URL(nameURL);
	        in = url.openStream();
            out = new FileOutputStream(nameFile);

	        // Now copy bytes from the URL to the output stram
	        byte[] buffer = new byte[4096];
	        int bytes_read;
	        while((bytes_read = in.read(buffer)) != -1)
	          out.write(buffer, 0, bytes_read);
	    }
	    // On exceptions, print error message and usage message
	    catch (Exception e) {
          System.err.println(e);
  	      System.err.println("Usage: java GetURL <URL> [<filename>]");
	    }
	    finally { // Always close the stream
	      try{ in.close(); out.close(); } catch(Exception e) {}
	    }
	}
}